		curNode := current.node()
		if curNode.prefixLen > 0 {
			// Check how much of the prefix matches the node's prefix
			prefixLen := current.match(prefix, keyOffset)
			matchedPrefixLen := minInt(int(curNode.prefixLen), maxPrefixLen)

			// If there's a mismatch in the node's prefix
			if prefixLen < matchedPrefixLen {
				// If we've consumed the entire prefix, this node is where we start traversal
				if keyOffset+prefixLen == len(prefix) {
					return current
				}
				// Otherwise, there's no match
				return nil
			}

			// We matched the entire node prefix, advance the key offset
			keyOffset += matchedPrefixLen

			// If we've consumed the entire prefix, this node is where we start traversal
			if keyOffset == len(prefix) {
				return current
			}
		}

		// Continue to the child node
		next := current.findChildByKey(prefix, keyOffset)
		if *next != nil {
			current = *next
			keyOffset++
		} else {
			// No child for the next character in the prefix
			// But if we've matched the entire prefix so far, this node is where we start traversal
			if keyOffset == len(prefix) {
				return current
			}
			return nil
		}
	}

	return current
}

func (tr *tree) forEachPrefix(key Key, callback Callback, opts int) traverseAction {
	// Keep only leaf and reverse options
	opts &= (TraverseLeaf | TraverseReverse)

	// Find the node that matches the prefix
	prefixNode := tr.findPrefixNode(key)
	if prefixNode == nil {
		// No node matches the prefix, nothing to traverse
		return traverseContinue
	}

	// Convert options to traverseOpts
	options := traverseOpts(opts)
	filteredCallback := traverseFilter(options, callback)

	// Traverse the subtree rooted at prefixNode
	return tr.forEachRecursively(prefixNode, filteredCallback, options.hasReverse())
}

